function minTiltAfterRemoval(nums: number[]): number {
  const n = nums.length / 3;
  let best = Infinity;
  for (let i = n; i <= 2 * n; i++) {
    const left = nums.slice(0, i).sort((a, b) => a - b).slice(0, n);
    const right = nums.slice(i).sort((a, b) => b - a).slice(0, n);
    const diff = left.reduce((s, x) => s + x, 0) - right.reduce((s, x) => s + x, 0);
    best = Math.min(best, diff);
  }
  return best;
}

