class MinHeap {
  a: number[] = [];
  get size() { return this.a.length; }
  push(v: number): void {
    const a = this.a;
    a.push(v);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p] <= a[i]) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }
  pop(): number {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length > 0) {
      a[0] = last;
      let i = 0;
      while (true) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l] < a[m]) m = l;
        if (r < a.length && a[r] < a[m]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

function minTiltAfterRemoval(nums: number[]): number {
  const n = nums.length / 3;
  const left = new Array(3 * n + 1).fill(0);
  const maxHeap = new MinHeap(); // stores negatives
  let sum = 0;
  for (let i = 0; i < 2 * n; i++) {
    maxHeap.push(-nums[i]);
    sum += nums[i];
    if (maxHeap.size > n) sum += maxHeap.pop(); // removes the largest
    if (i + 1 >= n) left[i + 1] = sum;
  }
  const minHeap = new MinHeap();
  sum = 0;
  let best = Infinity;
  for (let i = 3 * n - 1; i >= n; i--) {
    minHeap.push(nums[i]);
    sum += nums[i];
    if (minHeap.size > n) sum -= minHeap.pop();
    if (3 * n - i >= n) best = Math.min(best, left[i] - sum);
  }
  return best;
}

